  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 A Nation Divided: Slavery, Sections and the Road to War$j$, $j${"readings": [{"title": "Matthew 12 (King James Version)", "url": "/portal/bible/Matthew/12"}], "body": "Welcome to United States History. Historians of the United States use the same tools you learned in World History: primary sources, timelines, cause and effect, and fair weighing of evidence. Our course begins with the crisis that nearly broke the nation.\n\nThe Declaration of Independence in 1776 said that all men are created equal, yet slavery remained. By the 1800s the North had growing factories and cities, while the South depended on plantation farming and the labor of enslaved people. The nation argued over whether slavery would spread to new territories. Compromises, such as the Missouri Compromise of 1820 and the Compromise of 1850, delayed a break. The Fugitive Slave Act, the Kansas Nebraska Act and the Dred Scott decision of 1857 deepened anger. John Brown's raid at Harpers Ferry in 1859 shocked the country.\n\nIn 1860 Abraham Lincoln, who opposed the spread of slavery, was elected president. Seven Southern states left the Union before he took office, and four more followed after fighting began at Fort Sumter in April 1861. Matthew 12:25 says, Every kingdom divided against itself is brought to desolation; and every city or house divided against itself shall not stand.\n\nYour task: (1) Name two differences between the Northern and Southern economies. (2) Tell why the Dred Scott decision caused anger. (3) Explain what happened after Lincoln was elected.\n\nFlorida standards: SS.912.A.1, SS.912.A.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.1, SS.912.A.2", "script": "Welcome to United States History. I am Dr. Alex L. Jenkins Sr., and I am honored to walk with you through the story of our nation. Listen, this is the same craft you learned in World History. We use primary sources, timelines, cause and effect and fair weighing of evidence. And we begin with the crisis that nearly broke the nation.\n\nNow watch this. The Declaration of Independence in seventeen seventy six said that all men are created equal, yet slavery remained. By the eighteen hundreds the North had growing factories and cities, while the South depended on plantation farming and the labor of enslaved people. The nation argued over whether slavery would spread into new territories. Compromises, like the Missouri Compromise of eighteen twenty and the Compromise of eighteen fifty, delayed a break. The Fugitive Slave Act, the Kansas Nebraska Act and the Dred Scott decision of eighteen fifty seven deepened anger. John Brown's raid at Harpers Ferry in eighteen fifty nine shocked the country.\n\nLook at this. In eighteen sixty Abraham Lincoln, who opposed the spread of slavery, was elected president. Seven Southern states left the Union before he took office, and four more followed after fighting began at Fort Sumter in April of eighteen sixty one. Matthew twelve and twenty five says, Every kingdom divided against itself is brought to desolation; and every city or house divided against itself shall not stand.\n\nYour task today. Name two differences between the Northern and Southern economies. Tell why the Dred Scott decision caused anger. And explain what happened after Lincoln was elected. Take the four question check.\n\nA nation, like a house, needs a firm foundation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 A Nation Divided: Slavery, Sections and the Road to War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 The Civil War: Battles, Emancipation and Lincoln's Leadership$j$, $j${"readings": [{"title": "Psalm 133 (King James Version)", "url": "/portal/bible/Psalms/133"}], "body": "The Civil War lasted from 1861 to 1865 and cost about 620,000 soldiers' lives, the most of any American war. The Union, led by President Lincoln, sought to preserve the nation. The Confederacy, led by Jefferson Davis, sought independence.\n\nKey points:\nThe North had more people, factories and railroads. The South had skilled generals such as Robert E. Lee and fought on familiar ground.\nIn 1862 the Union stopped Lee at Antietam, the bloodiest single day in American history.\nOn January 1, 1863, Lincoln's Emancipation Proclamation declared enslaved people in rebel states free. It made ending slavery a goal of the war, and about 180,000 Black men served in the Union army and navy.\nIn July 1863 the Union won at Gettysburg and Vicksburg, turning the tide. At Gettysburg Lincoln spoke of a nation that would have a new birth of freedom, so that government of the people, by the people, for the people, shall not perish from the earth.\nGenerals Ulysses Grant and William Sherman wore down the South. Lee surrendered to Grant at Appomattox Court House on April 9, 1865. Five days later Lincoln was shot and died.\n\nPsalm 133:1 says, Behold, how good and how pleasant it is for brethren to dwell together in unity!\n\nYour task: (1) Give two advantages of the North. (2) Explain what the Emancipation Proclamation did and did not do. (3) Tell why Gettysburg and Vicksburg mattered.\n\nFlorida standards: SS.912.A.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.2", "script": "Welcome back. Listen, the Civil War lasted from eighteen sixty one to eighteen sixty five and cost about six hundred twenty thousand soldiers' lives, the most of any American war. The Union, led by President Lincoln, fought to preserve the nation. The Confederacy, led by Jefferson Davis, fought for independence.\n\nNow watch this. The North had more people, factories and railroads. The South had skilled generals like Robert E. Lee and fought on familiar ground. In eighteen sixty two the Union stopped Lee at Antietam, the bloodiest single day in American history. On January first, eighteen sixty three, Lincoln's Emancipation Proclamation declared enslaved people in the rebel states free. It made ending slavery a goal of the war, and about one hundred eighty thousand Black men served in the Union army and navy.\n\nLook at this. In July of eighteen sixty three the Union won at Gettysburg and Vicksburg, and the tide turned. At Gettysburg Lincoln spoke of a new birth of freedom, so that government of the people, by the people, for the people, shall not perish from the earth. Grant and Sherman wore down the South. Lee surrendered to Grant at Appomattox Court House on April ninth, eighteen sixty five, and five days later Lincoln was shot and died.\n\nPsalm one thirty three and one says, Behold, how good and how pleasant it is for brethren to dwell together in unity!\n\nYour task today. Give two advantages of the North. Explain what the Emancipation Proclamation did and did not do. And tell why Gettysburg and Vicksburg mattered. Take the four question check.\n\nLet us honor all who sacrificed. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 The Civil War: Battles, Emancipation and Lincoln's Leadership$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Reconstruction: Rebuilding the Nation and the New Amendments$j$, $j${"readings": [{"title": "Isaiah 61 (King James Version)", "url": "/portal/bible/Isaiah/61"}], "body": "Reconstruction (1865 to 1877) was the effort to rebuild the South and decide the place of freed people in American life.\n\nLincoln's plan was gentle, and after his death President Andrew Johnson offered easy terms to former Confederates. Southern states passed Black Codes that limited the rights of freed people. Congress, led by Radical Republicans, answered with stronger laws. Congress created the Freedmen's Bureau to provide food, schools and legal help. The Reconstruction Acts of 1867 placed the South under military districts.\n\nThree amendments changed the Constitution:\nThe 13th Amendment (1865) ended slavery.\nThe 14th Amendment (1868) made all persons born in the United States citizens and promised equal protection of the law.\nThe 15th Amendment (1870) said that the right to vote could not be denied because of race.\n\nFreed people built churches, schools and colleges, and many Black men were elected to local and state offices. Hiram Revels of Mississippi became the first Black member of the Senate. Congress impeached Andrew Johnson in 1868, and he stayed in office by one vote in the Senate. Isaiah 61:1 says that God sends his servant to proclaim liberty to the captives, and the opening of the prison to them that are bound.\n\nYour task: (1) Define Black Codes and tell why Congress opposed them. (2) Match each amendment to its purpose. (3) Name two things freed people built in this period.\n\nFlorida standards: SS.912.A.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.2", "script": "Welcome back. Listen, Reconstruction, from eighteen sixty five to eighteen seventy seven, was the effort to rebuild the South and decide the place of freed people in American life.\n\nNow watch this. Lincoln's plan was gentle, and after his death President Andrew Johnson offered easy terms to former Confederates. Southern states passed Black Codes that limited the rights of freed people. Congress, led by the Radical Republicans, answered with stronger laws. It created the Freedmen's Bureau to provide food, schools and legal help, and the Reconstruction Acts of eighteen sixty seven placed the South under military districts.\n\nLook at this. Three amendments changed the Constitution. The Thirteenth ended slavery. The Fourteenth made all persons born in the United States citizens and promised equal protection of the law. The Fifteenth said the right to vote could not be denied because of race.\n\nFreed people built churches, schools and colleges, and many Black men were elected to local and state offices. Hiram Revels of Mississippi became the first Black member of the Senate. Congress impeached Andrew Johnson in eighteen sixty eight, and he stayed in office by one vote. Isaiah sixty one and one says that God sends his servant to proclaim liberty to the captives, and the opening of the prison to them that are bound.\n\nYour task today. Define Black Codes and tell why Congress opposed them. Match each amendment to its purpose. And name two things freed people built. Take the four question check.\n\nFreedom is a gift to be protected. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Reconstruction: Rebuilding the Nation and the New Amendments$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 The End of Reconstruction and the Rise of Jim Crow$j$, $j${"readings": [{"title": "Amos 5 (King James Version)", "url": "/portal/bible/Amos/5"}], "body": "Reconstruction faced fierce resistance. Groups such as the Ku Klux Klan used terror to keep Black citizens from voting and holding office, and Congress passed Enforcement Acts to fight them. Many Northerners grew tired of the effort, and economic trouble after the Panic of 1873 distracted the nation.\n\nThe presidential election of 1876 was disputed. In the Compromise of 1877, Republican Rutherford B. Hayes became president and federal troops left the South. Reconstruction ended, and white Democratic leaders took control of Southern governments.\n\nNext came Jim Crow, a system of segregation laws and customs. Poll taxes and literacy tests kept most Black men from voting. Sharecropping tied many farm families to debt on the land they worked. In Plessy v. Ferguson (1896), the Supreme Court approved separate but equal facilities, though they were rarely equal. Lynching spread terror. Yet Black Americans kept building churches, businesses, schools and newspapers. Booker T. Washington founded programs at Tuskegee Institute, and Ida B. Wells reported on lynching and demanded justice.\n\nAmos 5:24 says, But let judgment run down as waters, and righteousness as a mighty stream.\n\nYour task: (1) Explain how the Compromise of 1877 ended Reconstruction. (2) Define two tools used to take away the vote. (3) Tell what Plessy v. Ferguson said and why it was wrong.\n\nFlorida standards: SS.912.A.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.2", "script": "Welcome back. Listen, Reconstruction faced fierce resistance. Groups like the Ku Klux Klan used terror to keep Black citizens from voting and holding office, and Congress passed Enforcement Acts to fight them. Many Northerners grew tired of the effort, and the Panic of eighteen seventy three distracted the nation.\n\nNow watch this. The election of eighteen seventy six was disputed. In the Compromise of eighteen seventy seven Republican Rutherford B. Hayes became president and federal troops left the South. Reconstruction ended, and white Democratic leaders took control of Southern governments.\n\nLook at this. Then came Jim Crow, a system of segregation laws and customs. Poll taxes and literacy tests kept most Black men from voting. Sharecropping tied many farm families to debt on the land they worked. In Plessy versus Ferguson, eighteen ninety six, the Supreme Court approved separate but equal facilities, though they were rarely equal. Lynching spread terror. Yet Black Americans kept building churches, businesses, schools and newspapers. Booker T. Washington built Tuskegee Institute, and Ida B. Wells reported on lynching and demanded justice.\n\nAmos five and twenty four says, But let judgment run down as waters, and righteousness as a mighty stream.\n\nYour task today. Explain how the Compromise of eighteen seventy seven ended Reconstruction. Define two tools used to take away the vote. And tell what Plessy versus Ferguson said and why it was wrong. Take the four question check.\n\nJustice delayed is not justice forgotten before God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 The End of Reconstruction and the Rise of Jim Crow$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Causes, Course and Consequences of the Civil War$j$, $j${"prompt": "Write a clear report on the Civil War and Reconstruction. Use complete sentences and label each part. Amos 5:24 says, But let judgment run down as waters, and righteousness as a mighty stream.\n\nPart 1: Explain three causes of the Civil War, including slavery, and tell the immediate trigger.\nPart 2: Describe two turning points of the war and explain why each mattered.\nPart 3: Explain what the Emancipation Proclamation did, and tell how Black soldiers helped win the war.\nPart 4: Explain the purpose of the 13th, 14th and 15th Amendments.\nPart 5: Explain why Reconstruction ended and how Jim Crow grew.\nPart 6: Choose one primary source from this unit (for example, the Gettysburg Address or the 14th Amendment) and answer: who wrote it, when, why, and what it tells us.", "rubric": "70 points. Causes and trigger: 12 points. Turning points: 10 points. Emancipation and Black soldiers: 10 points. Amendments: 10 points. End of Reconstruction and Jim Crow: 14 points. Primary source analysis: 10 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Causes, Course and Consequences of the Civil War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Union, Freedom and Justice$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why slavery was the central cause of the Civil War, (2) tells how the 13th, 14th and 15th Amendments tried to correct that wrong, (3) describes why Reconstruction's promises were not fully kept, and (4) connects your answer to Psalm 133:1, which says, Behold, how good and how pleasant it is for brethren to dwell together in unity! Then write a respectful reply of at least 40 words to another student, or answer this question: Why do you think the Gettysburg Address is still read today? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Union, Freedom and Justice$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: A Nation Divided: Slavery, Sections and the Road to War$j$, $j${"questions": [{"q": "The South's economy in the 1850s depended mainly on:", "options": ["Plantation farming and enslaved labor", "Fishing fleets only", "Computer industry", "Large steel mills"]}, {"q": "The fighting of the Civil War began at:", "options": ["Gettysburg", "Harpers Ferry", "Fort Sumter", "Appomattox"]}, {"q": "Who was elected president in 1860?", "options": ["Abraham Lincoln", "Ulysses Grant", "James Buchanan", "Jefferson Davis"]}, {"q": "The Dred Scott decision of 1857 said that:", "options": ["Slaves were free in the North", "Kansas was a free state", "Black Americans could not be citizens and Congress could not ban slavery in the territories", "Slavery was ended"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: A Nation Divided: Slavery, Sections and the Road to War$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2}'::int[], array[$j$Cotton and other crops grown on plantations made slavery central to the Southern economy.$j$,$j$Confederate forces fired on Fort Sumter in April 1861.$j$,$j$Lincoln won without carrying any Southern state.$j$,$j$The Supreme Court's ruling outraged many in the North.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: A Nation Divided: Slavery, Sections and the Road to War$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: The Civil War: Battles, Emancipation and Lincoln's Leadership$j$, $j${"questions": [{"q": "The Emancipation Proclamation took effect on:", "options": ["April 9, 1865", "April 12, 1861", "January 1, 1863", "July 4, 1776"]}, {"q": "Which battle was the bloodiest single day in American history?", "options": ["Fort Sumter", "Gettysburg", "Vicksburg", "Antietam"]}, {"q": "Lee surrendered to Grant at:", "options": ["Richmond", "Appomattox Court House", "Gettysburg", "Savannah"]}, {"q": "Which was an advantage of the Union?", "options": ["Fighting on its own land", "More factories and railroads", "More slaves", "More cotton exports"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Civil War: Battles, Emancipation and Lincoln's Leadership$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$Lincoln issued it as a war measure that declared slaves in rebel states free.$j$,$j$Over 22,000 were killed, wounded or missing at Antietam.$j$,$j$The surrender on April 9, 1865 effectively ended the war in Virginia.$j$,$j$The North's industry and population supported a long war.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: The Civil War: Battles, Emancipation and Lincoln's Leadership$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Reconstruction: Rebuilding the Nation and the New Amendments$j$, $j${"questions": [{"q": "The 13th Amendment:", "options": ["Gave women the vote", "Ended slavery", "Created income tax", "Ended Prohibition"]}, {"q": "The 14th Amendment guaranteed:", "options": ["A national bank", "Citizenship and equal protection of the law", "The vote for women", "Free land in the West"]}, {"q": "The Freedmen's Bureau helped freed people with:", "options": ["Land in Florida only", "Railroad building", "Food, schools and legal aid", "War loans"]}, {"q": "Southern Black Codes were laws that:", "options": ["Created colleges", "Protected voting", "Limited the rights of freed people", "Ended taxes"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Reconstruction: Rebuilding the Nation and the New Amendments$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,2,2}'::int[], array[$j$It abolished slavery in the United States.$j$,$j$It defined citizenship for all persons born in the United States.$j$,$j$The bureau also helped with labor contracts.$j$,$j$They restricted work, movement and property for freed people.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Reconstruction: Rebuilding the Nation and the New Amendments$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The End of Reconstruction and the Rise of Jim Crow$j$, $j${"questions": [{"q": "Reconstruction ended with the:", "options": ["Louisiana Purchase", "Emancipation Proclamation", "Compromise of 1877", "Treaty of Versailles"]}, {"q": "Plessy v. Ferguson (1896) approved:", "options": ["Women's suffrage", "School integration", "Equal schools for all", "Separate but equal facilities"]}, {"q": "Sharecropping was a system in which farmers:", "options": ["Owned large farms", "Gave part of their crop for use of land and often fell into debt", "Received free land", "Worked in factories"]}, {"q": "A poll tax and a literacy test were used to:", "options": ["Raise army troops", "Help immigrants", "Keep Black citizens from voting", "Pay for schools"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The End of Reconstruction and the Rise of Jim Crow$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,2}'::int[], array[$j$Federal troops left the South after Hayes became president.$j$,$j$The decision supported segregation until it was overturned.$j$,$j$Many families were trapped in cycles of debt.$j$,$j$They were barriers aimed at denying the vote.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The End of Reconstruction and the Rise of Jim Crow$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: A House Divided, the Civil War and Reconstruction$j$, $j${"questions": [{"q": "Which president led the Union during the Civil War?", "options": ["Abraham Lincoln", "James Polk", "Ulysses Grant", "Andrew Johnson"]}, {"q": "The Civil War began in:", "options": ["1861", "1776", "1898", "1812"]}, {"q": "The Union victories of July 1863 were at:", "options": ["Gettysburg and Vicksburg", "Richmond and Savannah", "Fort Sumter and Atlanta", "Antietam and Bull Run"]}, {"q": "The 15th Amendment protected the right to vote regardless of:", "options": ["Age", "Race", "Gender", "Wealth"]}, {"q": "Andrew Johnson's presidency is known for:", "options": ["Easy terms for the South and impeachment", "Buying Alaska only", "Ending the war", "Writing the Gettysburg Address"]}, {"q": "Jim Crow laws were designed to:", "options": ["Support unions", "Protect equal rights", "Help freed people buy land", "Enforce segregation"]}, {"q": "The Ku Klux Klan used violence to:", "options": ["Stop Black citizens from voting and holding office", "Help the Freedmen's Bureau", "Elect Lincoln", "Build schools"]}, {"q": "The Gettysburg Address spoke of a government of the people, by the people and:", "options": ["For the people", "Over the people", "Near the people", "Without the people"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: A House Divided, the Civil War and Reconstruction$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,1,0,3,0,0}'::int[], array[$j$Lincoln led the Union from 1861 to 1865.$j$,$j$Fort Sumter was fired on in April 1861.$j$,$j$These victories turned the tide.$j$,$j$It barred denying the vote because of race or previous servitude.$j$,$j$Congress opposed his policies and impeached him in 1868.$j$,$j$They separated people by race in public life.$j$,$j$Congress passed Enforcement Acts to fight it.$j$,$j$The phrase is from Lincoln's 1863 speech.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: A House Divided, the Civil War and Reconstruction$j$ on conflict (item_id) do nothing;
